def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        if hp <= 2 or no_water >= 1:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    total_players = 1 + len(alive)
    expected_units = supply / float(WATER_REQ)
    scarcity = expected_units < total_players

    opp_signals = []
    urgent_count = 0
    rich_count = 0
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        prev_bid = prev.get('bid')
        if prev_bid is None:
            prev_bid = opp.get('daily_salary', DAILY_SALARY) * 0.55
        opp_hp = opp.get('hp', 10)
        opp_nowater = opp.get('no_water_days', 0)
        opp_budget = opp.get('budget', 0)
        opp_salary = opp.get('daily_salary', DAILY_SALARY)

        urgency_bonus = 0.0
        if opp_nowater >= 1:
            urgency_bonus += opp_salary * 0.18
        if opp_hp <= 3:
            urgency_bonus += opp_salary * 0.14
        if opp_budget >= opp_salary * 8:
            rich_count += 1
            urgency_bonus += opp_salary * 0.06
        if opp_nowater >= 1 or opp_hp <= 3:
            urgent_count += 1

        signal = float(prev_bid) + float(urgency_bonus)
        opp_signals.append(signal)

    highest_signal = max(opp_signals) if opp_signals else DAILY_SALARY * 0.55
    avg_signal = sum(opp_signals) / float(len(opp_signals)) if opp_signals else DAILY_SALARY * 0.55

    my_urgent = (hp <= 3) or (no_water >= 1)
    my_critical = (hp <= 2) or (no_water >= 2)

    if my_critical:
        bid = max(DAILY_SALARY * 0.95, highest_signal + 2.5)
    elif my_urgent:
        bid = max(DAILY_SALARY * 0.82, highest_signal + 1.5)
    else:
        if scarcity:
            bid = max(DAILY_SALARY * 0.58, avg_signal + 1.0)
            if urgent_count >= 2:
                bid = max(bid, highest_signal + 1.8)
        else:
            bid = DAILY_SALARY * 0.34
            if day >= 8:
                bid = DAILY_SALARY * 0.42
            if highest_signal < DAILY_SALARY * 0.45:
                bid = max(bid, highest_signal + 0.8)

    if rich_count >= 2 and not my_urgent and not scarcity:
        bid *= 0.92

    if budget < DAILY_SALARY * 1.2:
        if my_urgent:
            bid = max(bid, budget * 0.92)
        else:
            bid = min(bid, budget * 0.7)

    bid = min(float(budget), float(bid))
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from immediate previous_trace
    prev_bids = []
    prev_by_id = {}
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
            except Exception:
                continue
            prev_bids.append(b)
            prev_by_id[opp_id] = b

    # Estimate how many allocations we might need: if supply is tight vs WATER_REQ, prioritize.
    # Since bids compete for limited supply, higher supply reduces pressure.
    # supply_per_unit_factor: how many WATER_REQ blocks fit
    blocks = supply / float(WATER_REQ) if WATER_REQ > 0 else 0.0
    # If blocks < 2, water is scarce; if >=2, less scarce.
    scarce = blocks < 2.0

    # Determine top opponent bid pressure
    top_bid = max(prev_bids) if prev_bids else 0.0

    # Base bid target: aim around a fraction of daily salary.
    # Undercut the top bid when it was very high to win at lower cost.
    if scarce:
        base = DAILY_SALARY * 0.62
    else:
        base = DAILY_SALARY * 0.48

    # If we are in danger (no water days or low hp), bid harder.
    if my_hp <= 2 or my_no_water_days >= 1:
        base = max(base, DAILY_SALARY * 0.82)

    # If someone previously bid extremely high, slightly undercut.
    # Use int() only for list indices; here we just compare floats.
    if top_bid >= DAILY_SALARY * 0.85:
        # Underbid just enough: target a bit below top_bid but still above our base.
        target = max(base, top_bid - 2.0)
    elif top_bid >= DAILY_SALARY * 0.65:
        target = max(base, top_bid - 4.0)
    else:
        # No extreme pressure: bid near base but not too high.
        target = base

    # Safety cap: never bid above what we can afford.
    # Also avoid reckless spending when hp is healthy.
    if my_hp >= 7 and my_no_water_days == 0:
        cap = DAILY_SALARY * 0.75
    else:
        cap = DAILY_SALARY * 0.95

    bid = min(my_budget, min(cap, target))

    # If budget is extremely low, still bid something to avoid guaranteed no-water days.
    if bid <= 0.0:
        bid = min(my_budget, DAILY_SALARY * 0.2)

    return float(bid)
